"""Authored opportunity notes, never generated by substituting player statistics."""
import json
from pathlib import Path

LIBRARY = Path(__file__).with_name('board-reads.json')


def load_board_reads(players, canonical_revision=None, path=LIBRARY, *, deployment_path=None):
    bundle = json.loads(Path(path).read_text())
    from deployment import verify_editorial_review
    verify_editorial_review(bundle, deployment_path) if deployment_path else verify_editorial_review(bundle)
    if canonical_revision and canonical_revision != bundle['canonicalRevision']:
        raise ValueError('Board reads require review against the new canonical snapshot')
    by_id = {str(p['playerId']): p for p in players}
    notes = {}
    for note in bundle['items']:
        pid = note['playerId']
        if pid in notes:
            raise ValueError(f'Duplicate board read: {pid}')
        player = by_id.get(pid)
        if player is None:
            continue
        # Fail rather than silently carrying a team/opportunity claim into a
        # different snapshot. These are existing projections, not assignments.
        for field in ('name', 'team', 'line', 'powerPlay'):
            if player.get(field) != note[field]:
                raise ValueError(f'Board read requires editorial review: {pid} {field}')
        if not note['body'].strip() or len(note['body'].split()) > 60 or '\u2014' in note['body']:
            raise ValueError(f'Invalid board read copy: {pid}')
        if note.get('url') and not note['url'].startswith('https://'):
            raise ValueError(f'Invalid board read source: {pid}')
        notes[pid] = note
    return notes


# An editorial shortlist, not a page-fill quota. Every selection has a specific
# reader decision; having a researched paragraph does not itself earn a feature.
# Roles remain canonical projected scenarios, never confirmed assignments.
