def select_board_features(players, notes, weights):
    """Select editorial subjects across the whole board BEFORE pagination.

    Neither rank, row index, page size nor paragraph availability is a reason.
    A category-dependent feature requires a material positive contribution.
    This threshold checks relevance; it never alters projections or rankings.
    """
    selected={}
    for p in players:
        pid=str(p['playerId'])
        if pid not in FEATURES:continue
        label,reason,category=FEATURES[pid]
        contribution=None
        if category:
            from customer_data import raw_totals
            totals=raw_totals(p);configured=weights.get('skater',{})
            weight=configured.get(category,0);value=totals.get(category)
            if weight<=0 or value is None:continue
            contribution=value*weight
            positive=sum(v*configured.get(k,0) for k,v in totals.items()
                         if v is not None and configured.get(k,0)>0)
            if positive<=0 or contribution/positive<.15:continue
        if pid not in notes:
            raise ValueError('Selected editorial feature needs an authored read: '+pid)
        selected[pid]=dict(label=label,reason=reason,category=category,
                           categoryContribution=contribution)
    return selected
